const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envPath = path.join(__dirname, '.env.test');

function resolveConnectionString() {
  let dbUrl = process.env.DATABASE_URL;

  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('DATABASE_URL=')) {
        dbUrl = trimmed.substring('DATABASE_URL='.length);
        break;
      }
    }
  }

  if (dbUrl) {
    console.log(`Connected successfully to database at ${dbUrl}`);
  } else {
    console.log('Warning: DATABASE_URL not found in .env.test or environment variables.');
  }
}

function simulateMigrations() {
  try {
    resolveConnectionString();

    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory not found at ${migrationsDir}`);
      return;
    }

    // Read all files in the directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them alphabetically/numerically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('Pending migrations to apply:');
    // Log each file in order
    for (const file of sqlFiles) {
      console.log(`Applying: ${file}`);
    }

    console.log('All migrations applied successfully (simulated).');
  } catch (error) {
    console.error('Error reading migrations directory:', error);
  }
}

simulateMigrations();

