function getDatabaseUrl() {
  let dbUrl = process.env.DATABASE_URL;
  try {
    if (fs.existsSync(envPath)) {
      const envContent = fs.readFileSync(envPath, 'utf8');
      const lines = envContent.split('\n');
      for (const line of lines) {
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          dbUrl = trimmedLine.substring('DATABASE_URL='.length).trim();
          // Remove quotes if present
          if ((dbUrl.startsWith('"') && dbUrl.endsWith('"')) || (dbUrl.startsWith("'") && dbUrl.endsWith("'"))) {
            dbUrl = dbUrl.substring(1, dbUrl.length - 1);
          }
          break;
        }
      }
    }
  } catch (error) {
    console.error('Error reading .env.test:', error);
  }
  return dbUrl;
}

function simulateMigrations() {
  try {
    const dbUrl = getDatabaseUrl();
    if (dbUrl) {
      console.log(`Connected successfully to database at: ${dbUrl}`);
